import io
import sys
from rich.file_proxy import FileProxy
from rich.console import Console

def test_isatty_proxy():
    console = Console(force_terminal=True)
    # Create a mock file that has isatty returning True
    class MockFile(io.TextIOBase):
        def isatty(self):
            return True
        def write(self, s):
            pass
        def flush(self):
            pass

    mock_file = MockFile()
    print(f"MockFile isatty: {mock_file.isatty()}")

    proxy = FileProxy(console, mock_file)
    print(f"FileProxy isatty: {proxy.isatty()}")

    assert proxy.isatty() == True, f"FileProxy.isatty() should be True, but got {proxy.isatty()}"

if __name__ == "__main__":
    try:
        test_isatty_proxy()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

